#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using Yarn.Unity;
public sealed class ChainRelationsCapture:MonoBehaviour
{
    string output;int checks;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(!Environment.GetCommandLineArgs().Contains("-chain-relations-capture"))return;Application.runInBackground=true;var dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/ChainRelations"));Directory.CreateDirectory(dir);SaveGames.TestRoot=Path.Combine(dir,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.besieged.json");var go=new GameObject("Chain and relations verification");DontDestroyOnLoad(go);go.AddComponent<ChainRelationsCapture>().output=dir;}
    void Check(bool yes,string message){if(!yes)throw new Exception(message);checks++;}
    IEnumerator Start(){var work=new Stack<IEnumerator>();work.Push(Run());while(work.Count>0){object next=null;bool more=false;try{more=work.Peek().MoveNext();if(more)next=work.Peek().Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"checks.txt"),"FAILED "+checks+"\n"+ex);Application.Quit(1);yield break;}if(!more){work.Pop();continue;}if(next is IEnumerator inner)work.Push(inner);else yield return next;}File.WriteAllText(Path.Combine(output,"checks.txt"),checks+" checks passed");Application.Quit(0);}
    IEnumerator Run(){AudioListener.volume=0;yield return null;SaveMenu.StartCampaign(false);float end=Time.realtimeSinceStartup+30;while(!VariableSingleton.IsInitialized&&Time.realtimeSinceStartup<end)yield return null;Check(VariableSingleton.IsInitialized,"campaign initialized");yield return new WaitForSecondsRealtime(.5f);CampaignHUD.Instance.DismissReport();var baseline=VariableSingleton.Instance.CaptureState();var manager=FindObjectOfType<ManagerUI>(true);var council=CouncilUI.For(manager);var ui=FindObjectOfType<EventUI>(true);var runner=ui.GetComponentInChildren<DialogueRunner>(true);
        for(int choice=0;choice<4;choice++){
            council.Hide();CampaignHUD.Instance.DismissReport();if(runner.IsDialogueRunning)runner.Stop();ui.gameObject.SetActive(false);var state=JsonUtility.FromJson<VariableSingleton.CampaignSave>(JsonUtility.ToJson(baseline));VariableSingleton.Instance.RestoreValidated(state);VariableSingleton.ChangeBool("bGoldenHornChain",true);VariableSingleton.SetInt("iOttomanHornAccess",0);VariableSingleton.ChangeBool("bCharArtillerist5",true);VariableSingleton.SetInt("iMoney",100000);int cannons=DailyLifeEvents.I("iCannons"),ammo=DailyLifeEvents.I("iAmmunition");manager.gameObject.SetActive(false);ui.SetStartNode("story19");ui.gameObject.SetActive(true);
            for(int i=0;i<200&&!FindObjectsOfType<OptionButton>().Any(o=>o.IsInteractable());i++)yield return new WaitForSecondsRealtime(.03f);
            string[] keys={"They are fools","Scrap it and sell","use the metal to cast","greatest cannon in the world"};var option=FindObjectsOfType<OptionButton>().First(o=>o.IsInteractable()&&o.Option.Line.Text.Text.Contains(keys[choice]));option.InvokeOptionSelected();for(int i=0;i<400&&runner.IsDialogueRunning;i++)yield return new WaitForSecondsRealtime(.03f);
            Check(!runner.IsDialogueRunning,"choice resolved "+choice);Check(VariableSingleton.GetBoolVariable("bGoldenHornChain")== (choice==0),"chain fate matches actual choice "+choice);Check(DefencePosture.HornOpen==(choice!=0),"harbour access follows chain choice "+choice);
            if(choice==2)Check(DailyLifeEvents.I("iCannons")==cannons+10&&DailyLifeEvents.I("iAmmunition")==ammo+100&&DailyLifeEvents.I("iMoney")==95000,"cannon and ammunition rewards unchanged");
            ui.gameObject.SetActive(false);CampaignHUD.Instance.DismissReport();council.Fleet();yield return null;yield return null;var chain=FindObjectOfType<FleetChainBackdrop>();Check(chain!=null,"chain background adapter present");Check(chain.transform.parent.GetComponent<RawImage>().texture.name==SceneBackdrop.Phase("fleet")+(choice==0?"":"-no-chain"),"correct chain artwork after choice "+choice);Check(chain.GetComponent<LocationHotspot>().raycastTarget==(choice==0),"removed chain cannot be hovered "+choice);
        }
        foreach(int width in new[]{1280,1600}){Screen.SetResolution(width,width==1280?720:900,false);yield return new WaitForSecondsRealtime(1.5f);council.DiplomaticRelations();yield return null;Canvas.ForceUpdateCanvases();var panel=GameObject.Find("Council screen");Check(panel.GetComponentsInChildren<TMP_Text>().Any(t=>t.text=="Relations Overview"),"overview renamed "+width);var labels=panel.GetComponentsInChildren<Button>().Select(b=>b.GetComponentInChildren<TMP_Text>(true)).Where(t=>t!=null).ToArray();Check(labels.Any(t=>t.text=="Diplomacy and Court")&&labels.Any(t=>t.text=="War Beyond the Walls"),"both footer destinations "+width);
            foreach(var row in panel.GetComponentsInChildren<RectTransform>().Where(r=>r.name=="Diplomatic standing"&&r.parent.name.StartsWith("Diplomatic court")))Check(row.anchorMin.x>=.175f,"standing clears flag column "+width);
            yield return Capture(width+"-relations");panel.GetComponentsInChildren<Button>().Single(b=>b.GetComponentInChildren<TMP_Text>()?.text=="War Beyond the Walls").onClick.Invoke();yield return null;Check(GameObject.Find("War Beyond the Walls map")!=null,"left footer opens map "+width);WarTheatreUI.Close();yield return null;panel.GetComponentsInChildren<Button>().Single(b=>b.GetComponentInChildren<TMP_Text>()?.text=="Diplomacy and Court").onClick.Invoke();yield return null;Check(GameObject.Find("Council screen").GetComponentsInChildren<TMP_Text>().Any(t=>t.text=="Diplomacy and court"),"right footer returns diplomacy and court "+width);
        }
    }
    IEnumerator Capture(string name){yield return null;Canvas.ForceUpdateCanvases();var go=new GameObject("Capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cams=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var prior=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=prior;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cams[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
